## Theme Switcher

### Uso Básico

```typescript
// En tu componente
import { ThemeSwitcherComponent } from './shared/components/theme-switcher/theme-switcher.component';

@Component({
  standalone: true,
  imports: [ThemeSwitcherComponent],
  template: `<app-theme-switcher></app-theme-switcher>`
})
export class MyComponent {}
```

### Uso Avanzado con el Servicio

```typescript
import { Component, OnInit } from '@angular/core';
import { ThemeService, Theme } from './core/services/theme.service';

@Component({
  selector: 'app-settings',
  template: `
    <div class="settings">
      <h2>Configuración de Tema</h2>
      <p>Tema actual: {{ currentTheme }}</p>

      <button (click)="setLightTheme()">Tema Claro</button>
      <button (click)="setDarkTheme()">Tema Oscuro</button>
      <button (click)="toggleTheme()">Alternar</button>
    </div>
  `
})
export class SettingsComponent implements OnInit {
  currentTheme: Theme = 'light';

  constructor(private themeService: ThemeService) {}

  ngOnInit(): void {
    this.themeService.theme$.subscribe(theme => {
      this.currentTheme = theme;
      console.log('Tema cambiado a:', theme);
    });
  }

  setLightTheme(): void {
    this.themeService.setTheme('light');
  }

  setDarkTheme(): void {
    this.themeService.setTheme('dark');
  }

  toggleTheme(): void {
    this.themeService.toggleTheme();
  }
}
```

