## Accordion

### FAQ Básico

```typescript
import { AccordionComponent, AccordionItemComponent } from './shared/components/accordion/accordion.component';

@Component({
  imports: [AccordionComponent, AccordionItemComponent],
  template: `
    <div class="faq-section">
      <h2>Preguntas Frecuentes</h2>

      <app-accordion>
        <app-accordion-item 
          title="¿Cómo hacer una reserva?"
          [isOpen]="true">
          <p>Para hacer una reserva, sigue estos pasos:</p>
          <ol>
            <li>Selecciona tu destino</li>
            <li>Elige las fechas</li>
            <li>Completa el formulario</li>
            <li>Realiza el pago</li>
          </ol>
        </app-accordion-item>

        <app-accordion-item title="¿Métodos de pago?">
          <p>Aceptamos:</p>
          <ul>
            <li>Tarjetas de crédito/débito</li>
            <li>PayPal</li>
            <li>Transferencia bancaria</li>
          </ul>
        </app-accordion-item>
      </app-accordion>
    </div>
  `
})
export class FAQComponent {}
```

### Accordion Dinámico

```typescript
interface FAQItem {
  id: string;
  question: string;
  answer: string;
  isOpen?: boolean;
}

@Component({
  template: `
    <app-accordion>
      <app-accordion-item 
        *ngFor="let item of faqItems"
        [title]="item.question"
        [isOpen]="item.isOpen"
        [id]="item.id">
        <p>{{ item.answer }}</p>
      </app-accordion-item>
    </app-accordion>
  `
})
export class DynamicFAQComponent {
  faqItems: FAQItem[] = [
    {
      id: '1',
      question: '¿Cómo cancelar mi reserva?',
      answer: 'Puedes cancelar hasta 48h antes...',
      isOpen: true
    },
    {
      id: '2',
      question: '¿Hay descuentos para grupos?',
      answer: 'Sí, ofrecemos descuentos especiales...'
    }
  ];
}
```

