## Tabs

### Tabs Básicas

```typescript
import { TabsComponent, TabPanelComponent, Tab } from './shared/components/tabs/tabs.component';

@Component({
  imports: [TabsComponent, TabPanelComponent],
  template: `
    <app-tabs 
      [tabs]="tabs" 
      [activeTabId]="activeTab"
      (tabChanged)="onTabChange($event)">

      <app-tab-panel 
        [tabId]="'info'" 
        [active]="activeTab === 'info'">
        <h3>Información</h3>
        <p>Contenido de información...</p>
      </app-tab-panel>

      <app-tab-panel 
        [tabId]="'reviews'" 
        [active]="activeTab === 'reviews'">
        <h3>Reseñas</h3>
        <p>Contenido de reseñas...</p>
      </app-tab-panel>

      <app-tab-panel 
        [tabId]="'map'" 
        [active]="activeTab === 'map'">
        <h3>Mapa</h3>
        <p>Contenido del mapa...</p>
      </app-tab-panel>
    </app-tabs>
  `
})
export class ProductDetailsComponent {
  tabs: Tab[] = [
    { id: 'info', label: 'Información', icon: 'ℹ️' },
    { id: 'reviews', label: 'Reseñas', icon: '⭐' },
    { id: 'map', label: 'Ubicación', icon: '' }
  ];

  activeTab = 'info';

  onTabChange(tabId: string): void {
    this.activeTab = tabId;
    console.log('Tab activa:', tabId);
  }
}
```

### Tabs con Datos Dinámicos

```typescript
interface Destination {
  id: string;
  name: string;
  icon: string;
  description: string;
  attractions: string[];
}

@Component({
  template: `
    <app-tabs 
      [tabs]="destinationTabs" 
      [activeTabId]="selectedDestination"
      (tabChanged)="loadDestination($event)">

      <app-tab-panel 
        *ngFor="let dest of destinations"
        [tabId]="dest.id" 
        [active]="selectedDestination === dest.id">

        <div class="destination-detail">
          <h2>{{ dest.name }}</h2>
          <p>{{ dest.description }}</p>

          <h3>Atracciones</h3>
          <ul>
            <li *ngFor="let attraction of dest.attractions">
              {{ attraction }}
            </li>
          </ul>
        </div>
      </app-tab-panel>
    </app-tabs>
  `
})
export class DestinationsComponent implements OnInit {
  destinations: Destination[] = [];
  destinationTabs: Tab[] = [];
  selectedDestination = '';

  ngOnInit(): void {
    this.loadDestinations();
  }

  loadDestinations(): void {
    this.destinations = [
      {
        id: 'barcelona',
        name: 'Barcelona',
        icon: '',
        description: 'Ciudad cosmopolita...',
        attractions: ['Sagrada Familia', 'Park Güell', 'Las Ramblas']
      },
      {
        id: 'paris',
        name: 'París',
        icon: '',
        description: 'La ciudad del amor...',
        attractions: ['Torre Eiffel', 'Louvre', 'Notre Dame']
      }
    ];

    this.destinationTabs = this.destinations.map(d => ({
      id: d.id,
      label: d.name,
      icon: d.icon
    }));

    this.selectedDestination = this.destinations[0].id;
  }

  loadDestination(id: string): void {
    console.log('Cargando destino:', id);
    // Lógica para cargar más datos si es necesario
  }
}
```

