## Hamburger Menu

### Menu Responsive Básico

```typescript
import { HamburgerMenuComponent } from './shared/components/hamburger-menu/hamburger-menu.component';

@Component({
  imports: [HamburgerMenuComponent],
  template: `
    <header>
      <div class="logo">T4 Traveling</div>

      <nav class="desktop-nav">
        <a href="#home">Inicio</a>
        <a href="#destinations">Destinos</a>
        <a href="#about">Nosotros</a>
        <a href="#contact">Contacto</a>
      </nav>

      <app-hamburger-menu [(isOpen)]="isMenuOpen">
        <nav class="mobile-nav">
          <a href="#home" (click)="closeMenu()">Inicio</a>
          <a href="#destinations" (click)="closeMenu()">Destinos</a>
          <a href="#about" (click)="closeMenu()">Nosotros</a>
          <a href="#contact" (click)="closeMenu()">Contacto</a>
        </nav>
      </app-hamburger-menu>
    </header>
  `,
  styles: [`
    .desktop-nav {
      display: none;

      @media (min-width: 1024px) {
        display: flex;
        gap: 2rem;
      }
    }
  `]
})
export class HeaderComponent {
  isMenuOpen = false;

  closeMenu(): void {
    this.isMenuOpen = false;
  }
}
```

### Menu con Submenús

```typescript
@Component({
  template: `
    <app-hamburger-menu [(isOpen)]="isMenuOpen">
      <nav class="mobile-nav">
        <div class="nav-section">
          <h3>Destinos</h3>
          <a href="#europe" (click)="closeMenu()">Europa</a>
          <a href="#asia" (click)="closeMenu()">Asia</a>
          <a href="#america" (click)="closeMenu()">América</a>
        </div>

        <div class="nav-section">
          <h3>Servicios</h3>
          <a href="#flights" (click)="closeMenu()">Vuelos</a>
          <a href="#hotels" (click)="closeMenu()">Hoteles</a>
          <a href="#packages" (click)="closeMenu()">Paquetes</a>
        </div>

        <div class="nav-section">
          <h3>Mi Cuenta</h3>
          <a href="#profile" (click)="closeMenu()">Perfil</a>
          <a href="#bookings" (click)="closeMenu()">Mis Reservas</a>
          <a href="#logout" (click)="logout()">Cerrar Sesión</a>
        </div>
      </nav>
    </app-hamburger-menu>
  `
})
export class AdvancedMenuComponent {
  isMenuOpen = false;

  closeMenu(): void {
    this.isMenuOpen = false;
  }

  logout(): void {
    console.log('Cerrando sesión...');
    this.closeMenu();
  }
}
```

