## Combinando Componentes

### Dashboard Completo

```typescript
@Component({
  imports: [
    ThemeSwitcherComponent,
    ModalComponent,
    TabsComponent,
    TabPanelComponent,
    HamburgerMenuComponent,
    TooltipDirective
  ],
  template: `
    <div class="dashboard">
      <header>
        <h1>Panel de Control</h1>
        <div class="header-actions">
          <button 
            appTooltip="Notificaciones"
            tooltipPosition="bottom">

          </button>
          <app-theme-switcher></app-theme-switcher>
          <app-hamburger-menu [(isOpen)]="isMenuOpen">
            <nav>
              <a href="#dashboard">Dashboard</a>
              <a href="#bookings">Reservas</a>
              <a href="#profile">Perfil</a>
            </nav>
          </app-hamburger-menu>
        </div>
      </header>

      <main>
        <app-tabs 
          [tabs]="tabs" 
          [activeTabId]="activeTab"
          (tabChanged)="onTabChange($event)">

          <app-tab-panel 
            [tabId]="'overview'" 
            [active]="activeTab === 'overview'">
            <h2>Resumen</h2>
            <!-- Contenido del dashboard -->
          </app-tab-panel>

          <app-tab-panel 
            [tabId]="'bookings'" 
            [active]="activeTab === 'bookings'">
            <h2>Mis Reservas</h2>
            <button (click)="openBookingModal()">
              Ver Detalles
            </button>
          </app-tab-panel>
        </app-tabs>
      </main>

      <app-modal 
        [isOpen]="isModalOpen"
        [title]="'Detalles de Reserva'"
        (closed)="closeModal()">
        <!-- Contenido del modal -->
      </app-modal>
    </div>
  `
})
export class DashboardComponent {
  isMenuOpen = false;
  isModalOpen = false;
  activeTab = 'overview';

  tabs: Tab[] = [
    { id: 'overview', label: 'Resumen', icon: '' },
    { id: 'bookings', label: 'Reservas', icon: '' }
  ];

  onTabChange(tabId: string): void {
    this.activeTab = tabId;
  }

  openBookingModal(): void {
    this.isModalOpen = true;
  }

  closeModal(): void {
    this.isModalOpen = false;
  }
}
```

---

## Tips y Mejores Prácticas

### 1. Performance
```typescript
// ✅ Usar OnPush para mejor rendimiento
@Component({
  changeDetection: ChangeDetectionStrategy.OnPush
})
```

### 2. Limpieza de Recursos
```typescript
// ✅ Limpiar subscripciones
ngOnDestroy(): void {
  this.subscription?.unsubscribe();
}
```

### 3. Accesibilidad
```typescript
// ✅ Añadir atributos ARIA
<button 
  aria-label="Abrir modal"
  aria-expanded="false">
```

### 4. Responsive Design
```typescript
// ✅ Adaptar comportamiento según viewport
@HostListener('window:resize')
onResize(): void {
  if (window.innerWidth > 1024) {
    this.isMenuOpen = false;
  }
}
```

